class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        def find(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a
        pos = {}
        for i, v in enumerate(nums):
            if v <= threshold:
                pos[v] = i
        for g in range(1, threshold + 1):
            first = -1
            for m in range(g, threshold + 1, g):
                if m in pos:
                    if first == -1:
                        first = pos[m]
                    else:
                        ra, rb = find(first), find(pos[m])
                        if ra != rb:
                            parent[ra] = rb
        return len({find(i) for i in range(n)})

