class Solution {
    public int countComponents(int[] nums, int threshold) {
        int n = nums.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        java.util.function.IntUnaryOperator find = new java.util.function.IntUnaryOperator() {
            public int applyAsInt(int a) {
                while (parent[a] != a) { parent[a] = parent[parent[a]]; a = parent[a]; }
                return a;
            }
        };
        Map<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < n; i++)
            if (nums[i] <= threshold) pos.put(nums[i], i);
        for (int g = 1; g <= threshold; g++) {
            int first = -1;
            for (int m = g; m <= threshold; m += g) {
                Integer idx = pos.get(m);
                if (idx == null) continue;
                if (first == -1) first = idx;
                else {
                    int ra = find.applyAsInt(first), rb = find.applyAsInt(idx);
                    if (ra != rb) parent[ra] = rb;
                }
            }
        }
        Set<Integer> roots = new HashSet<>();
        for (int i = 0; i < n; i++) roots.add(find.applyAsInt(i));
        return roots.size();
    }
}

