            if (pos.has(m)) {
                if (first === -1) first = pos.get(m);
                else {
                    const ra = find(first), rb = find(pos.get(m));
                    if (ra !== rb) parent[ra] = rb;
                }
            }
        }
    }
    return new Set(nums.map((_, i) => find(i))).size;
